<section class="wrap flow-card"><span class="flow-icon">✳</span>
<?php if($banned): ?><h1><?= e($t('account.banned')) ?></h1><p><?= e($t('account.banned.info')) ?></p><a class="button outline" href="<?= $url('contact') ?>"><?= e($t('nav.contact')) ?></a>
<?php elseif($user && $user['storage_user_id'] && $user['status']==='active'): ?>
<h1><?= e($t('status.ready')) ?></h1><p><?= e($t('status.onboard')) ?></p><ol class="onboarding"><?php foreach([4,5,6] as $i): ?><li><?= e($t('step.'.$i.'.desc')) ?></li><?php endforeach ?></ol>
<?php if(env('MOBILE_SERVICE_URL')): ?><p><?= e($t('status.service')) ?>: <strong><?= e(env('MOBILE_SERVICE_URL')) ?></strong></p><?php endif ?>
<div class="actions"><?php foreach(['IOS','ANDROID'] as $platform): if(env('MOBILE_'.$platform.'_URL')): ?><a class="button outline" href="<?= e(env('MOBILE_'.$platform.'_URL')) ?>"><?= e($t('status.download')) ?> · <?= $platform==='IOS'?'iOS':'Android' ?> ↗</a><?php endif; endforeach ?></div>
<?php elseif($user && $eligible && $automaticActivation): ?><h1><?= e($t('status.activating')) ?></h1><p role="status"><?= e($t('status.automatic')) ?></p>
<form method="post" action="<?= $url('activate') ?>"<?= $activationDue?' data-auto-activation':'' ?>><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="automatic" value="1"><button class="button"><?= e($t('continue')) ?> ↻</button></form>
<?php if(!$activationDue): ?><span data-status-poll hidden></span><?php endif ?>
<?php elseif($user && $eligible): ?><h1><?= e($t('status.activate')) ?></h1><p><?= e($t('status.password')) ?></p><form method="post" action="<?= $url('activate') ?>"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><label for="password"><?= e($t('form.password')) ?></label><input id="password" name="password" type="password" autocomplete="current-password" required><?php if(!$user['terms_at'] || !$user['privacy_at']): ?><label><input name="accept" type="checkbox" value="1" required><?= e($t('account.accept')) ?></label><?php endif ?><button class="button full"><?= e($t('continue')) ?> ↗</button></form>
<?php else: ?><?php if($user && $user['email_verified_at']): ?><span data-status-poll hidden></span><?php endif ?><h1><?= e($t('status.title')) ?></h1><p><?= e($t($user && $user['email_verified_at']?'status.wait':'status.verify')) ?></p><a class="button" href="<?= $url('status') ?>"><?= e($t('continue')) ?> ↻</a><?php endif ?>
<?php if($user && $user['selected_plan_id']!=='free'): ?><form class="recovery" method="post" action="<?= $url('portal') ?>"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><button class="text-link"><?= e($t('status.billing')) ?> ↗</button></form><?php endif ?>
</section>
<?php if($user && $user['selected_plan_id']!=='free'): ?><div class="wrap billing-shortcut"><a class="text-link" href="<?= $url('billing-profile') ?>"><?= e($t('billing.title')) ?> · <?= e($t('billing.history')) ?> ↗</a></div><?php endif ?>

<?php if($user && ($upgradeOffers || $latestChange)): ?><div class="wrap billing-shortcut"><a class="button outline" href="<?= $url('upgrade') ?>"><?= e($t('upgrade.title')) ?> ↗</a></div><?php endif ?>
